using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Diagnostics;using System.Security.Cryptography;using System.Windows.Forms;using System.Drawing;using System.Web.Script.Serialization;using Microsoft.Win32;
[assembly:AssemblyTitle("Installer Control · Seraphim")]
[assembly:AssemblyVersion("0.16.1.0")]
static class Setup {
 const string Product="Seraphim.Share.0161";
 static string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Seraphim");
 static JavaScriptSerializer Json=new JavaScriptSerializer {MaxJsonLength=4000000};
 public class Entry {public Entry(){}public string path;public string sha256;public long size;}
 static string SafePath(string root,string name){if(String.IsNullOrEmpty(name)||name.Contains(":")||Path.IsPathRooted(name))throw new IOException("Chemin de paquet invalide.");string full=Path.GetFullPath(Path.Combine(root,name.Replace('/',Path.DirectorySeparatorChar)));if(!full.StartsWith(Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Chemin hors du dossier d’installation.");return full;}
 static string Hash(Stream input){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
 static void Payload(Action<ZipArchive,List<Entry>> action){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){var manifest=zip.GetEntry("package-files.json");if(manifest==null)throw new IOException("Inventaire absent.");List<Entry> files;using(var reader=new StreamReader(manifest.Open()))files=Json.Deserialize<List<Entry>>(reader.ReadToEnd());var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var file in files){SafePath(Root,file.path);if(!names.Add(file.path))throw new IOException("Fichier en double.");var item=zip.GetEntry(file.path);if(item==null||item.Length!=file.size)throw new IOException("Fichier incomplet : "+file.path);using(var content=item.Open())if(Hash(content)!=file.sha256)throw new IOException("Fichier modifié : "+file.path);}if(zip.Entries.Count!=files.Count+1)throw new IOException("Inventaire incomplet.");action(zip,files);}}
 static bool Running(){return Process.GetProcessesByName("Seraphim").Any(p=>{try{return String.Equals(p.MainModule.FileName,Path.Combine(Root,"Seraphim.exe"),StringComparison.OrdinalIgnoreCase);}catch{return false;}});}
 static void Host(string folder,string finalRoot){var manifest=new {name="com.seraphim.control",description="Control Seraphim Desktop Bridge",path=Path.Combine(finalRoot,"Seraphim.exe"),type="stdio",allowed_origins=new[]{"chrome-extension://ipefdjlgbcfgkbghknckpljcjbffdhdh/"}};File.WriteAllText(Path.Combine(folder,"native-host.json"),Json.Serialize(manifest),new System.Text.UTF8Encoding(false));}
 static void Shortcut(string file,string target,string icon){Type t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);dynamic link=shell.CreateShortcut(file);link.TargetPath=target;link.WorkingDirectory=Root;link.IconLocation=icon+",0";link.Save();System.Runtime.InteropServices.Marshal.ReleaseComObject(link);System.Runtime.InteropServices.Marshal.ReleaseComObject(shell);}
 static void Register(bool desktop){string manifest=Path.Combine(Root,"native-host.json");foreach(string vendor in new[]{"Google\\Chrome","Chromium","Microsoft\\Edge"})using(var key=Registry.CurrentUser.CreateSubKey("Software\\"+vendor+"\\NativeMessagingHosts\\com.seraphim.control"))key.SetValue("",manifest);
  using(var key=Registry.CurrentUser.CreateSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Seraphim")){key.SetValue("DisplayName","Control · Seraphim");key.SetValue("DisplayVersion","0.16.1");key.SetValue("Publisher","Seraphim");key.SetValue("InstallLocation",Root);key.SetValue("DisplayIcon",Path.Combine(Root,"Seraphim-Premium.ico"));key.SetValue("UninstallString","\""+Path.Combine(Root,"Desinstaller.exe")+"\"");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}
  string start=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Seraphim");Directory.CreateDirectory(start);Shortcut(Path.Combine(start,"Seraphim.lnk"),Path.Combine(Root,"Seraphim.exe"),Path.Combine(Root,"Seraphim-Premium.ico"));Shortcut(Path.Combine(start,"Installation des extensions.lnk"),Path.Combine(Root,"BIENVENUE.html"),Path.Combine(Root,"Control.ico"));if(desktop)Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Seraphim.lnk"),Path.Combine(Root,"Seraphim.exe"),Path.Combine(Root,"Seraphim-Premium.ico"));
 }
 static void Install(string target,bool register,bool desktop){if(register&&Running())throw new IOException("Quittez Seraphim depuis son icône près de l’horloge, puis relancez l’installation.");if(Directory.Exists(target)&&(!register||!File.Exists(Path.Combine(target,"installation-seraphim.txt"))||File.ReadAllText(Path.Combine(target,"installation-seraphim.txt"))!=Product))throw new IOException("Ce dossier existe déjà sans marqueur Seraphim. Aucun fichier n’a été remplacé.");string stage=target+".staging-"+Guid.NewGuid().ToString("N"),old=target+".previous-"+Guid.NewGuid().ToString("N");bool moved=false;
  try{Payload((zip,files)=>{Directory.CreateDirectory(stage);foreach(var file in files){string output=SafePath(stage,file.path);Directory.CreateDirectory(Path.GetDirectoryName(output));using(var input=zip.GetEntry(file.path).Open())using(var dest=File.Create(output))input.CopyTo(dest);}using(var input=zip.GetEntry("package-files.json").Open())using(var dest=File.Create(Path.Combine(stage,"package-files.json")))input.CopyTo(dest);});Host(stage,target);File.WriteAllText(Path.Combine(stage,"installation-seraphim.txt"),Product);if(Directory.Exists(target)){Directory.Move(target,old);moved=true;}Directory.Move(stage,target);if(register)Register(desktop);if(moved)Directory.Delete(old,true);
  }catch{if(moved){if(Directory.Exists(target))Directory.Delete(target,true);Directory.Move(old,target);}throw;}finally{if(Directory.Exists(stage))Directory.Delete(stage,true);}
 }
 [STAThread]static int Main(string[] args){try{if(args.Length==2&&args[0]=="--verify"){Payload((z,f)=>File.WriteAllText(args[1],"PASS "+f.Count+" fichiers, tailles et SHA-256 vérifiés.\n"));return 0;}if(args.Length==2&&args[0]=="--test-install"){Install(Path.GetFullPath(args[1]),false,false);return 0;}if(args.Length==2&&args[0]=="--update"){if(!File.Exists(Path.Combine(Root,"installation-seraphim.txt"))||File.ReadAllText(Path.Combine(Root,"installation-seraphim.txt"))!=Product)throw new IOException("Installation gérée absente.");int pid;if(!Int32.TryParse(args[1],out pid)||pid<0)throw new IOException("Processus invalide.");if(pid>0)try{var running=Process.GetProcessById(pid);if(String.Equals(running.MainModule.FileName,Path.Combine(Root,"Seraphim.exe"),StringComparison.OrdinalIgnoreCase)&&!running.WaitForExit(30000))throw new IOException("Seraphim doit être fermé avant la mise à jour.");}catch(ArgumentException){}Install(Root,true,false);Process.Start(new ProcessStartInfo(Path.Combine(Root,"Seraphim.exe")){UseShellExecute=true});MessageBox.Show("Seraphim a été mis à jour. Vos données sont conservées. Dans Chrome/Edge, rechargez l’extension puis les onglets ouverts.","Mise à jour terminée");return 0;}Application.EnableVisualStyles();var form=new Form {Text="Installer Control · Seraphim",Width=590,Height=450,StartPosition=FormStartPosition.CenterScreen,BackColor=Color.FromArgb(20,21,29),ForeColor=Color.White,Font=new Font("Segoe UI",10),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false};var heading=new Label {Text="Votre temps. Votre espace.",Left=32,Top=28,Width=510,Height=48,Font=new Font("Segoe UI",22)};var copy=new Label {Text="Seraphim pour Windows, les extensions et Control pour iPhone.\nInstallation pour votre compte Windows, sans administrateur.",Left=34,Top=91,Width=510,Height=60};var destination=new Label {Text="Destination\n"+Root,Left=34,Top=166,Width=510,Height=65,ForeColor=Color.LightGray};var desktop=new CheckBox {Text="Créer le raccourci sur le bureau",Checked=true,Left=34,Top=239,Width=470};var note=new Label {Text="Les extensions se chargent ensuite depuis le guide.\nVos paramètres et votre compte restent sur votre PC.",Left=34,Top=278,Width=500,Height=45,ForeColor=Color.LightGray};var button=new Button {Text="Installer Seraphim",Left=34,Top=340,Width=500,Height=44,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(189,169,228),ForeColor=Color.FromArgb(20,21,29)};form.Controls.AddRange(new Control[]{heading,copy,destination,desktop,note,button});button.Click+=delegate {button.Enabled=false;button.Text="Vérification et installation…";form.Refresh();try{Install(Root,true,desktop.Checked);button.Text="Ouvrir le guide de démarrage";button.Enabled=true;MessageBox.Show(form,"Seraphim est installé. Le guide va vous aider à charger l’extension et préparer votre iPhone.","Installation terminée",MessageBoxButtons.OK,MessageBoxIcon.Information);Process.Start(new ProcessStartInfo(Path.Combine(Root,"BIENVENUE.html")){UseShellExecute=true});form.Close();}catch(Exception ex){MessageBox.Show(form,ex.Message,"Installation interrompue",MessageBoxButtons.OK,MessageBoxIcon.Error);button.Enabled=true;button.Text="Réessayer l’installation";}};Application.Run(form);return 0;}catch(Exception ex){if(args.Length==2&&args[0]!="--update")File.WriteAllText(args[1]+".error.txt",ex.ToString());else MessageBox.Show(ex.Message,"Seraphim");return 1;}}
}
